WITH items(item) AS (SELECT value FROM json_each(?1,'$.builtins') UNION ALL SELECT value FROM json_each(?1,'$.versions')) SELECT json(item) AS "entry:json" FROM items WHERE instr(unicode_fold(coalesce(item->>'$.id',item->>'$.name','')),unicode_fold(coalesce(?2,'')))>0 OR instr(unicode_fold(coalesce(item->>'$.description',item->>'$.contract','')),unicode_fold(coalesce(?2,'')))>0 LIMIT 128
